{
  nixFlake ? builtins.getFlake ("git+file://" + toString ../../..),
  system ? builtins.currentSystem,
  pkgs ? nixFlake.inputs.nixpkgs.legacyPackages.${system},
  nixComponents ? (
    nixFlake.lib.makeComponents {
      inherit pkgs;
      inherit getStdenv;
    }
  ),
  getStdenv ? p: p.stdenv,
  componentTestsPrefix ? "",
  withSanitizers ? false,
  withCoverage ? false,
  ...
}:

let
  inherit (pkgs) lib;
  hydraJobs = nixFlake.hydraJobs;
  packages' = nixFlake.packages.${system};
  stdenv = (getStdenv pkgs);

  collectCoverageLayer = finalAttrs: prevAttrs: {
    env =
      let
        # https://clang.llvm.org/docs/SourceBasedCodeCoverage.html#the-code-coverage-workflow
        coverageFlags = [
          "-fprofile-instr-generate"
          "-fcoverage-mapping"
        ];
      in
      {
        CFLAGS = toString coverageFlags;
        CXXFLAGS = toString coverageFlags;
      };

    # Done in a pre-configure hook, because $NIX_BUILD_TOP needs to be substituted.
    preConfigure = prevAttrs.preConfigure or "" + ''
      mappingFlag=" -fcoverage-prefix-map=$NIX_BUILD_TOP/${finalAttrs.src.name}=${finalAttrs.src}"
      CFLAGS+="$mappingFlag"
      CXXFLAGS+="$mappingFlag"
    '';
  };

  componentOverrides = (lib.optional withCoverage collectCoverageLayer);
in

rec {
  nixComponentsInstrumented = nixComponents.overrideScope (
    final: prev: {
      withASan = withSanitizers;
      withUBSan = withSanitizers;
      withFuzzer = withSanitizers;
      # Build the fuzz targets in CI.
      withFuzzTargets = withSanitizers;

      nix-store-tests = prev.nix-store-tests.override { withBenchmarks = true; };
      nix-expr-tests = prev.nix-expr-tests.override { withBenchmarks = true; };
      # Boehm is incompatible with ASAN.
      nix-expr = prev.nix-expr.override { enableGC = !withSanitizers; };

      mesonComponentOverrides = lib.composeManyExtensions componentOverrides;
    }
  );

  nixComponentsFuzzerOnly = nixComponents.overrideScope (
    _: _: {
      withUnitTests = false;
      withASan = withSanitizers;
      withUBSan = withSanitizers;
      withFuzzer = withSanitizers;
      withFuzzTargets = withSanitizers;
      mesonComponentOverrides = lib.composeManyExtensions componentOverrides;
    }
  );

  # Import NixOS tests using the instrumented components
  nixosTests = import ../../../tests/nixos {
    inherit lib pkgs;
    nixComponents = nixComponentsInstrumented;
    nixpkgs = nixFlake.inputs.nixpkgs;
    inherit (nixFlake.inputs) nixpkgs-23-11;
  };

  /**
    Top-level tests for the flake outputs, as they would be built by hydra.
    These tests generally can't be overridden to run with sanitizers.
  */
  topLevel = {
    installerScriptForGHA = hydraJobs.installerScriptForGHA.${system};
    daemonCompat = hydraJobs.tests.daemonCompat.${system};
    nixpkgsLibTests = hydraJobs.tests.nixpkgsLibTests.${system};
    filetransfer-retry-backoff = hydraJobs.tests.filetransfer-retry-backoff.${system};
    rl-next = pkgs.buildPackages.runCommand "test-rl-next-release-notes" { } ''
      LANG=C.UTF-8 ${pkgs.changelog-d}/bin/changelog-d ${../../../doc/manual/rl-next} >$out
    '';
    repl-completion = pkgs.callPackage ../../../tests/repl-completion.nix { inherit (packages') nix; };

    /**
      Checks for our packaging expressions.
      This shouldn't build anything significant; just check that things
      (including derivations) are _set up_ correctly.
    */
    packaging-overriding =
      let
        nix = packages'.nix;
        checkFuzzConfiguration =
          withUnitTests: withFuzzer: withFuzzTargets:
          let
            components = nixComponents.overrideScope (
              _: _: {
                inherit withUnitTests withFuzzer withFuzzTargets;
              }
            );
          in
          lib.all
            (
              name:
              let
                flags = components.${name}.mesonFlags;
              in
              lib.elem (lib.mesonBool "unit-tests" withUnitTests) flags
              && !(lib.elem (lib.mesonBool "unit-tests" (!withUnitTests)) flags)
              && ((lib.elem (lib.mesonOption "b_sanitize" "fuzzer-no-link") flags) == withFuzzer)
              && lib.elem (lib.mesonBool "fuzzers" withFuzzTargets) flags
              && !(lib.elem (lib.mesonBool "fuzzers" (!withFuzzTargets)) flags)
            )
            [
              "nix-util-tests"
              "nix-store-tests"
            ];
        fuzzerOnlyComponents = nixComponents.overrideScope (
          _: _: {
            withUnitTests = false;
            withFuzzTargets = true;
          }
        );
        emptyTestComponents = nixComponents.overrideScope (
          _: _: {
            withUnitTests = false;
            withFuzzTargets = false;
          }
        );
        emptyInstrumentedTestComponents = nixComponents.overrideScope (
          _: _: {
            withUnitTests = false;
            withFuzzer = true;
            withFuzzTargets = false;
          }
        );
        utilFuzzerOnly = fuzzerOnlyComponents.nix-util-tests;
        storeFuzzerOnly = fuzzerOnlyComponents.nix-store-tests;
      in
      assert (nix.appendPatches [ pkgs.emptyFile ]).libs.nix-util.src.patches == [ pkgs.emptyFile ];
      assert checkFuzzConfiguration false false true;
      assert checkFuzzConfiguration false true true;
      assert checkFuzzConfiguration true false false;
      assert checkFuzzConfiguration true false true;
      assert checkFuzzConfiguration true true false;
      assert checkFuzzConfiguration true true true;
      assert utilFuzzerOnly.buildInputs == [ (lib.getDev fuzzerOnlyComponents.nix-util) ];
      assert storeFuzzerOnly.buildInputs == [ (lib.getDev fuzzerOnlyComponents.nix-store) ];
      assert !(utilFuzzerOnly.tests ? run-without-new-syscalls);
      assert !(utilFuzzerOnly.meta ? mainProgram);
      assert !(storeFuzzerOnly.meta ? mainProgram);
      assert !(builtins.tryEval emptyTestComponents.nix-util-tests.drvPath).success;
      assert !(builtins.tryEval emptyTestComponents.nix-store-tests.drvPath).success;
      assert !(builtins.tryEval emptyInstrumentedTestComponents.nix-util-tests.drvPath).success;
      assert !(builtins.tryEval emptyInstrumentedTestComponents.nix-store-tests.drvPath).success;
      if pkgs.stdenv.buildPlatform.isDarwin then
        lib.warn "packaging-overriding check currently disabled because of a permissions issue on macOS" pkgs.emptyFile
      else
        # If this fails, something might be wrong with how we've wired the scope,
        # or something could be broken in Nixpkgs.
        pkgs.testers.testEqualContents {
          assertion = "trivial patch does not change source contents";
          expected = "${../../..}";
          actual =
            # Same for all components; nix-util is an arbitrary pick
            (nix.appendPatches [ pkgs.emptyFile ]).libs.nix-util.src;
        };
  };

  disable =
    let
      inherit (pkgs.stdenv) hostPlatform;
    in
    args@{
      pkgName,
      testName,
      test,
    }:
    lib.any (b: b) [
      # FIXME: Nix manual is impure and does not produce all settings on darwin
      (hostPlatform.isDarwin && pkgName == "nix-manual" && testName == "linkcheck")
    ];

  componentTests =
    (lib.concatMapAttrs (
      pkgName: pkg:
      lib.concatMapAttrs (
        testName: test:
        lib.optionalAttrs (!disable { inherit pkgName testName test; }) {
          "${componentTestsPrefix}${pkgName}-${testName}" = test;
        }
      ) (pkg.tests or { })
    ) nixComponentsInstrumented)
    // lib.optionalAttrs withSanitizers {
      "${componentTestsPrefix}nix-util-tests-fuzzer-only" =
        nixComponentsFuzzerOnly.nix-util-tests.tests.run;
      "${componentTestsPrefix}nix-store-tests-fuzzer-only" =
        nixComponentsFuzzerOnly.nix-store-tests.tests.run;
    }
    // lib.optionalAttrs (pkgs.stdenv.hostPlatform == pkgs.stdenv.buildPlatform) {
      "${componentTestsPrefix}nix-functional-tests" = nixComponentsInstrumented.nix-functional-tests;
      "${componentTestsPrefix}nix-json-schema-checks" = nixComponentsInstrumented.nix-json-schema-checks;
    };

  codeCoverage =
    let
      componentsTestsToProfile =
        (builtins.mapAttrs (n: v: nixComponentsInstrumented.${n}.tests.run) {
          "nix-util-tests" = { };
          "nix-store-tests" = { };
          "nix-fetchers-tests" = { };
          "nix-expr-tests" = { };
          "nix-flake-tests" = { };
        })
        // {
          inherit (nixComponentsInstrumented) nix-functional-tests;
        };

      coverageProfileDrvs = lib.mapAttrs (
        n: v:
        v.overrideAttrs (
          finalAttrs: prevAttrs: {
            outputs = (prevAttrs.outputs or [ "out" ]) ++ [ "profraw" ];
            env = {
              LLVM_PROFILE_FILE = "${placeholder "profraw"}/%m";
            };
          }
        )
      ) componentsTestsToProfile;

      coverageProfiles = lib.mapAttrsToList (n: v: lib.getOutput "profraw" v) coverageProfileDrvs;

      mergedProfdata =
        pkgs.runCommand "merged-profdata"
          {
            __structuredAttrs = true;
            nativeBuildInputs = [ pkgs.llvmPackages.libllvm ];
            inherit coverageProfiles;
          }
          ''
            rawProfiles=()
            for dir in "''\${coverageProfiles[@]}"; do
              rawProfiles+=($dir/*)
            done
            llvm-profdata merge -sparse -output $out "''\${rawProfiles[@]}"
          '';

      coverageReports =
        let
          nixComponentDrvs = lib.filter (lib.isDerivation) (lib.attrValues nixComponentsInstrumented);
        in
        pkgs.runCommand "code-coverage-report"
          {
            nativeBuildInputs = [
              pkgs.llvmPackages.libllvm
              pkgs.jq
            ];
            __structuredAttrs = true;
            nixComponents = nixComponentDrvs;
          }
          ''
            # ${toString (lib.map (v: v.src) nixComponentDrvs)}

            binaryFiles=()
            for dir in "''\${nixComponents[@]}"; do
              readarray -t filesInDir < <(find "$dir" -type f -executable)
              binaryFiles+=("''\${filesInDir[@]}")
            done

            arguments=$(concatStringsSep " -object " binaryFiles)
            llvm-cov show $arguments -instr-profile ${mergedProfdata} -output-dir $out -format=html

            {
              echo "# Code coverage summary (generated via \`llvm-cov\`):"
              echo
              echo '```'
              llvm-cov report $arguments -instr-profile ${mergedProfdata} -format=text -use-color=false
              echo '```'
              echo
            } >> $out/index.txt

            llvm-cov export $arguments -instr-profile ${mergedProfdata} -format=text > $out/coverage.json

            mkdir -p $out/nix-support

            coverageTotals=$(jq ".data[0].totals" $out/coverage.json)

            # Mostly inline from pkgs/build-support/setup-hooks/make-coverage-analysis-report.sh [1],
            # which we can't use here, because we rely on LLVM's infra for source code coverage collection.
            # [1]: https://github.com/NixOS/nixpkgs/blob/67bb48c4c8e327417d6d5aa7e538244b209e852b/pkgs/build-support/setup-hooks/make-coverage-analysis-report.sh#L16
            declare -A metricsArray=(["lineCoverage"]="lines" ["functionCoverage"]="functions" ["branchCoverage"]="branches")

            for metricName in "''\${!metricsArray[@]}"; do
              key="''\${metricsArray[$metricName]}"
              metric=$(echo "$coverageTotals" | jq ".$key.percent * 10 | round / 10")
              echo "$metricName $metric %" >> $out/nix-support/hydra-metrics
            done

            echo "report coverage $out" >> $out/nix-support/hydra-build-products
          '';
    in
    assert withCoverage;
    assert stdenv.cc.isClang;
    {
      inherit coverageProfileDrvs mergedProfdata coverageReports;
    };

  vmTests = {
    inherit (nixosTests) s3-binary-cache-store;
  }
  // lib.optionalAttrs (!withSanitizers && !withCoverage) {
    # evalNixpkgs uses non-instrumented components from hydraJobs, so only run it
    # when not testing with sanitizers to avoid rebuilding nix
    inherit (hydraJobs.tests) evalNixpkgs;
    # FIXME: CI times out when building vm tests instrumented
    inherit (nixosTests)
      functional_user
      githubFlakes
      nix-docker
      tarballFlakes
      ;
  };
}

{
  lib,
  officialRelease,
  src,
}:
rec {
  packageSetsFor =
    args@{
      pkgs,
      getStdenv ? pkgs: pkgs.stdenv,
    }:
    let
      nixComponentsSplices = lib.mapCrossIndex (
        pkgs': (packageSetsFor (args // { pkgs = pkgs'; })).nixComponents
      ) (lib.renameCrossIndexFrom "pkgs" pkgs);
      nixDependenciesSplices = lib.mapCrossIndex (
        pkgs': (packageSetsFor (args // { pkgs = pkgs'; })).nixDependencies
      ) (lib.renameCrossIndexFrom "pkgs" pkgs);

      # A new scope, so that we can use `callPackage` to inject our own interdependencies
      # without "polluting" the top level "`pkgs`" attrset.
      # This also has the benefit of providing us with a distinct set of packages
      # we can iterate over.
      nixComponents =
        lib.makeScopeWithSplicing'
          {
            inherit (pkgs) splicePackages;
            inherit (nixDependencies) newScope;
          }
          {
            otherSplices = lib.renameCrossIndexTo "self" nixComponentsSplices;
            f = import ./components.nix {
              inherit (pkgs) lib;
              inherit officialRelease;
              inherit pkgs;
              inherit src;
              maintainers = [ ];
            };
          };

      # The dependencies are in their own scope, so that they don't have to be
      # in Nixpkgs top level `pkgs` or `nixComponents`.
      nixDependencies =
        lib.makeScopeWithSplicing'
          {
            inherit (pkgs) splicePackages;
            inherit (pkgs) newScope; # layered directly on pkgs, unlike nixComponents above
          }
          {
            otherSplices = lib.renameCrossIndexTo "self" nixDependenciesSplices;
            f = import ./dependencies.nix {
              inherit pkgs;
              stdenv = getStdenv pkgs;
            };
          };

      # If the package set is largely empty, we should(?) return empty sets
      # This is what most package sets in Nixpkgs do. Otherwise, we get
      # an error message that indicates that some stdenv attribute is missing,
      # and indeed it will be missing, as seemingly `pkgsTargetTarget` is
      # very incomplete.
      fixup = lib.mapAttrs (k: v: if !(pkgs ? newScope) then { } else v);
    in
    fixup {
      inherit nixDependencies;
      inherit nixComponents;
    };
}

{
  lib,
  pkgs,
  src,
  officialRelease,
  maintainers,
}:

scope:

let
  inherit (scope)
    callPackage
    ;
  inherit
    (scope.callPackage (
      { stdenv }:
      {
        inherit stdenv;
      }
    ) { })
    stdenv
    ;
  inherit (pkgs.buildPackages)
    meson
    ninja
    pkg-config
    ;

  baseVersion = lib.fileContents ../.version;

  versionSuffix = lib.optionalString (!officialRelease) "pre";

  fineVersionSuffix =
    lib.optionalString (!officialRelease)
      "pre${
        builtins.substring 0 8 (src.lastModifiedDate or src.lastModified or "19700101")
      }_${src.shortRev or "dirty"}";

  fineVersion = baseVersion + fineVersionSuffix;

  root = ../.;

  # Indirection for Nixpkgs to override when package.nix files are vendored
  filesetToSource = lib.fileset.toSource;

  /**
    Given a stdenv and set of layers, create a mkDerivation-like function
  */
  mkPackageBuilderFor =
    stdenv': exts: userFn:
    stdenv'.mkDerivation (lib.extends (lib.composeManyExtensions exts) userFn);

  mkPackageBuilder = mkPackageBuilderFor stdenv;

  setVersionLayer = finalAttrs: prevAttrs: {
    preConfigure =
      prevAttrs.preConfigure or ""
      +
      # Update the repo-global .version file.
      # Symlink ./.version points there, but by default only workDir is writable.
      ''
        chmod u+w ./.version
        echo ${finalAttrs.version} > ./.version
      '';
  };

  localSourceLayer =
    finalAttrs: prevAttrs:
    let
      workDirPath =
        # Ideally we'd pick finalAttrs.workDir, but for now `mkDerivation` has
        # the requirement that everything except passthru and meta must be
        # serialized by mkDerivation, which doesn't work for this.
        prevAttrs.workDir;

      workDirSubpath = lib.path.removePrefix root workDirPath;
      sources =
        assert prevAttrs.fileset._type == "fileset";
        prevAttrs.fileset;
      src = lib.fileset.toSource {
        fileset = sources;
        inherit root;
      };

    in
    {
      sourceRoot = "${src.name}/" + workDirSubpath;
      inherit src;

      # Clear what `derivation` can't/shouldn't serialize; see prevAttrs.workDir.
      fileset = null;
      workDir = null;
    };

  resolveRelPath = p: lib.path.removePrefix root p;

  makeFetchedSourceLayer =
    finalScope: finalAttrs: prevAttrs:
    let
      workDirPath =
        # Ideally we'd pick finalAttrs.workDir, but for now `mkDerivation` has
        # the requirement that everything except passthru and meta must be
        # serialized by mkDerivation, which doesn't work for this.
        prevAttrs.workDir;

      workDirSubpath = resolveRelPath workDirPath;

    in
    {
      sourceRoot = "${finalScope.patchedSrc.name}/" + workDirSubpath;
      src = finalScope.patchedSrc;
      version =
        let
          n = lib.length finalScope.patches;
        in
        if n == 0 then prevAttrs.version else prevAttrs.version + "+${toString n}";

      # Clear what `derivation` can't/shouldn't serialize; see prevAttrs.workDir.
      fileset = null;
      workDir = null;
    };

  mesonLayer = finalAttrs: prevAttrs: {
    # NOTE:
    # As of https://github.com/NixOS/nixpkgs/blob/8baf8241cea0c7b30e0b8ae73474cb3de83c1a30/pkgs/by-name/me/meson/setup-hook.sh#L26,
    # `mesonBuildType` defaults to `plain` if not specified. We want our Nix-built binaries to be optimized by default.
    # More on build types here: https://mesonbuild.com/Builtin-options.html#details-for-buildtype.
    mesonBuildType = "release";
    # NOTE:
    # Users who are debugging Nix builds are expected to set the environment variable `mesonBuildType`, per the
    # guidance in https://github.com/NixOS/nix/blob/8a3fc27f1b63a08ac983ee46435a56cf49ebaf4a/doc/manual/source/development/debugging.md?plain=1#L10.
    # For this reason, we don't want to refer to `finalAttrs.mesonBuildType` here, but rather use the environment variable.
    preConfigure =
      prevAttrs.preConfigure or ""
      +
        lib.optionalString
          (
            !(stdenv.hostPlatform.isWindows || stdenv.hostPlatform.isCygwin)
            # build failure
            && !stdenv.hostPlatform.isStatic
          )
          ''
            case "$mesonBuildType" in
            release|minsize) appendToVar mesonFlags "-Db_lto=true"  ;;
            *)               appendToVar mesonFlags "-Db_lto=false" ;;
            esac
          '';
    nativeBuildInputs = [
      meson
      ninja
    ]
    ++ prevAttrs.nativeBuildInputs or [ ];
    mesonFlags =
      prevAttrs.mesonFlags or [ ]
      ++ (lib.optionals scope.withUnityBuild [
        "-Dunity=on"
        "-Dunity_size=8192"
        "-Db_pch=false"
      ]);
    mesonCheckFlags = prevAttrs.mesonCheckFlags or [ ] ++ [
      "--print-errorlogs"
    ];
  };

  mesonBuildLayer = finalAttrs: prevAttrs: rec {
    nativeBuildInputs = prevAttrs.nativeBuildInputs or [ ] ++ [
      pkg-config
    ];
    separateDebugInfo = !stdenv.hostPlatform.isStatic;
    # needed by separateDebugInfo
    # SEE: https://github.com/NixOS/nixpkgs/pull/394674/commits/a4d355342976e9e9823fb94f133bc43ebec9da5b
    __structuredAttrs = separateDebugInfo;
  };

  mesonLibraryLayer = finalAttrs: prevAttrs: {
    preConfigure =
      let
        interpositionFlags = [
          "-fno-semantic-interposition"
          "-Wl,-Bsymbolic-functions"
        ];
      in
      # NOTE: By default GCC disables interprocedular optimizations (in particular inlining) for
      # position-independent code and thus shared libraries.
      # Since LD_PRELOAD tricks aren't worth losing out on optimizations, we disable it for good.
      # This is not the case for Clang, where inlining is done by default even without -fno-semantic-interposition.
      # https://reviews.llvm.org/D102453
      # https://fedoraproject.org/wiki/Changes/PythonNoSemanticInterpositionSpeedup
      prevAttrs.preConfigure or ""
      + lib.optionalString stdenv.cc.isGNU ''
        export CFLAGS="''${CFLAGS:-} ${toString interpositionFlags}"
        export CXXFLAGS="''${CXXFLAGS:-} ${toString interpositionFlags}"
      '';
    outputs = prevAttrs.outputs or [ "out" ] ++ [ "dev" ];
  };

  fixupStaticLayer = finalAttrs: prevAttrs: {
    postFixup =
      prevAttrs.postFixup or ""
      + lib.optionalString (stdenv.hostPlatform.isStatic) ''
        # HACK: Otherwise the result will have the entire buildInputs closure
        # injected by the pkgsStatic stdenv
        # <https://github.com/NixOS/nixpkgs/issues/83667>
        rm -f $out/nix-support/propagated-build-inputs
      '';
  };

  # Work around weird `--as-needed` linker behavior with BSD, see
  # https://github.com/mesonbuild/meson/issues/3593
  bsdNoLinkAsNeeded =
    finalAttrs: prevAttrs:
    lib.optionalAttrs stdenv.hostPlatform.isBSD {
      mesonFlags = [ (lib.mesonBool "b_asneeded" false) ] ++ prevAttrs.mesonFlags or [ ];
    };

  enableSanitizersLayer =
    finalAttrs: prevAttrs:
    let
      sanitizers =
        lib.optional scope.withASan "address"
        ++ lib.optional scope.withUBSan "undefined"
        ++ lib.optional scope.withTSan "thread"
        ++ lib.optional scope.withFuzzer "fuzzer-no-link";
    in
    # Thread sanitizer can't be used with ASan or UBSan
    assert scope.withTSan -> !(scope.withASan || scope.withUBSan);
    {
      mesonFlags =
        (prevAttrs.mesonFlags or [ ])
        ++ lib.optionals (lib.length sanitizers > 0) (
          [
            (lib.mesonOption "b_sanitize" (lib.concatStringsSep "," sanitizers))
          ]
          ++ (lib.optionals stdenv.cc.isClang [
            # https://www.github.com/mesonbuild/meson/issues/764
            (lib.mesonBool "b_lundef" false)
          ])
        );
    };

  enableClangTidyLayer =
    finalAttrs: prevAttrs:
    lib.optionalAttrs scope.withClangTidy {
      nativeBuildInputs = (prevAttrs.nativeBuildInputs or [ ]) ++ [
        pkgs.buildPackages.llvmPackages.clang-tools # provides run-clang-tidy
      ];

      buildInputs = (prevAttrs.buildInputs or [ ]) ++ [
        scope.nix-clang-tidy-plugin # provides nix-clang-tidy.pc with plugin_path
      ];

      # Use debug build for faster compilation (no optimizations)
      mesonBuildType = "debug";

      # Skip tests - we only care about clang-tidy results
      doCheck = false;

      # Run clang-tidy after the normal build
      postBuild = (prevAttrs.postBuild or "") + ''
        echo "Running clang-tidy on ${finalAttrs.pname}..."
        ninja clang-tidy
      '';
    };

  nixDefaultsLayer = finalAttrs: prevAttrs: {
    strictDeps = prevAttrs.strictDeps or true;
    enableParallelBuilding = true;
    pos = builtins.unsafeGetAttrPos "pname" prevAttrs;
    meta = prevAttrs.meta or { } // {
      homepage = prevAttrs.meta.homepage or "https://nixos.org/nix";
      longDescription =
        prevAttrs.longDescription or ''
          Nix is a powerful package manager for mainly Linux and other Unix systems that
          makes package management reliable and reproducible. It provides atomic
          upgrades and rollbacks, side-by-side installation of multiple versions of
          a package, multi-user package management and easy setup of build
          environments.
        '';
      license = prevAttrs.meta.license or lib.licenses.lgpl21Plus;
      maintainers = prevAttrs.meta.maintainers or [ ] ++ scope.maintainers;
      platforms = prevAttrs.meta.platforms or (lib.platforms.unix ++ lib.platforms.windows);
    };
  };

  /**
    Append patches to the source layer.
  */
  appendPatches =
    scope: patches:
    scope.overrideScope (
      finalScope: prevScope: {
        patches = prevScope.patches ++ patches;
      }
    );

in

# This becomes the pkgs.nixComponents attribute set
{
  version = baseVersion + versionSuffix;
  inherit versionSuffix;
  inherit officialRelease;
  inherit maintainers;

  inherit filesetToSource;

  /**
    Whether meson components are built with [AddressSanitizer](https://clang.llvm.org/docs/AddressSanitizer.html).
  */
  withASan = false;

  /**
    Whether meson components are built with [UndefinedBehaviorSanitizer](https://clang.llvm.org/docs/UndefinedBehaviorSanitizer.html).
  */
  withUBSan = false;

  /**
    Whether meson components are built with [ThreadSanitizer](https://clang.llvm.org/docs/ThreadSanitizer.html).
  */
  withTSan = false;

  /**
    Whether meson components are built with [libFuzzer instrumentation](https://llvm.org/docs/LibFuzzer.html).
  */
  withFuzzer = false;

  /**
    Whether to build unit-test executables in Meson test components.
  */
  withUnitTests = true;

  /**
    Whether to build the libFuzzer targets in Meson test components.
  */
  withFuzzTargets = false;

  /**
    Whether meson components are checked with [clang-tidy](https://clang.llvm.org/extra/clang-tidy/).
  */
  withClangTidy = false;

  /**
    Whether to use [unity builds](https://mesonbuild.com/Unity-builds.html#unity-builds).
  */
  withUnityBuild = true;

  /**
    Whether to embed the public C API into nix-cli so plugins can resolve those symbols from the executable.
  */
  withPluginCAPI = !(stdenv.hostPlatform.isWindows || stdenv.hostPlatform.isStatic);

  /**
    A user-provided extension function to apply to each component derivation.
  */
  mesonComponentOverrides = finalAttrs: prevAttrs: { };

  /**
    An overridable derivation layer for handling the sources.
  */
  sourceLayer = localSourceLayer;

  /**
    Resolve a path value to either itself or a path in the `src`, depending
    whether `overrideSource` was called.
  */
  resolvePath = p: p;

  /**
    Apply an extension function (i.e. overlay-shaped) to all component derivations.
  */
  overrideAllMesonComponents =
    f:
    scope.overrideScope (
      finalScope: prevScope: {
        mesonComponentOverrides = lib.composeExtensions scope.mesonComponentOverrides f;
      }
    );

  /**
    Provide an alternate source. This allows the expressions to be vendored without copying the sources,
    but it does make the build non-granular; all components will use a complete source.

    Packaging expressions will be ignored.

    Single argument: the source to use.

    See also `appendPatches`
  */
  overrideSource =
    src:
    scope.overrideScope (
      finalScope: prevScope: {
        sourceLayer = makeFetchedSourceLayer finalScope;
        /**
          Unpatched source for the build of Nix. Packaging expressions will be ignored.
        */
        src = src;
        /**
          Patches for the whole Nix source. Changes to packaging expressions will be ignored.
        */
        patches = [ ];
        /**
          Fetched and patched source to be used in component derivations.
        */
        patchedSrc =
          if finalScope.patches == [ ] then
            src
          else
            pkgs.buildPackages.srcOnly (
              pkgs.buildPackages.stdenvNoCC.mkDerivation {
                name = "${finalScope.src.name or "nix-source"}-patched";
                inherit (finalScope) src patches;
              }
            );
        resolvePath = p: finalScope.patchedSrc + "/${resolveRelPath p}";
        filesetToSource = { root, fileset }: finalScope.resolvePath root;
        appendPatches = appendPatches finalScope;
      }
    );

  /**
    Append patches to be applied to the whole Nix source.
    This affects all components.

    Changes to the packaging expressions will be ignored.
  */
  appendPatches =
    patches:
    # switch to "fetched" source first, so that patches apply to the whole tree.
    (scope.overrideSource "${./..}").appendPatches patches;

  mkMesonDerivation = mkPackageBuilder [
    nixDefaultsLayer
    scope.sourceLayer
    setVersionLayer
    mesonLayer
    fixupStaticLayer
    enableSanitizersLayer
    scope.mesonComponentOverrides
  ];
  mkMesonExecutable = mkPackageBuilder [
    nixDefaultsLayer
    bsdNoLinkAsNeeded
    scope.sourceLayer
    setVersionLayer
    mesonLayer
    mesonBuildLayer
    fixupStaticLayer
    enableSanitizersLayer
    enableClangTidyLayer
    scope.mesonComponentOverrides
  ];
  mkMesonLibrary = mkPackageBuilder [
    nixDefaultsLayer
    bsdNoLinkAsNeeded
    scope.sourceLayer
    mesonLayer
    setVersionLayer
    mesonBuildLayer
    mesonLibraryLayer
    fixupStaticLayer
    enableSanitizersLayer
    enableClangTidyLayer
    scope.mesonComponentOverrides
  ];

  mkFuzzSeedCheck = callPackage ./fuzz-seed-check.nix { };

  nix-util = callPackage ../src/libutil/package.nix { };
  nix-util-c = callPackage ../src/libutil-c/package.nix { };
  nix-util-test-support = callPackage ../src/libutil-test-support/package.nix { };
  nix-util-tests = callPackage ../src/libutil-tests/package.nix { };

  nix-store = callPackage ../src/libstore/package.nix { };
  nix-store-c = callPackage ../src/libstore-c/package.nix { };
  nix-store-test-support = callPackage ../src/libstore-test-support/package.nix { };
  nix-store-tests = callPackage ../src/libstore-tests/package.nix { };

  nix-fetchers = callPackage ../src/libfetchers/package.nix { };
  nix-fetchers-c = callPackage ../src/libfetchers-c/package.nix { };
  nix-fetchers-tests = callPackage ../src/libfetchers-tests/package.nix { };

  nix-expr = callPackage ../src/libexpr/package.nix { };
  nix-expr-c = callPackage ../src/libexpr-c/package.nix { };
  nix-expr-test-support = callPackage ../src/libexpr-test-support/package.nix { };
  nix-expr-tests = callPackage ../src/libexpr-tests/package.nix { };

  nix-flake = callPackage ../src/libflake/package.nix { };
  nix-flake-c = callPackage ../src/libflake-c/package.nix { };
  nix-flake-tests = callPackage ../src/libflake-tests/package.nix { };

  nix-main = callPackage ../src/libmain/package.nix { };
  nix-main-c = callPackage ../src/libmain-c/package.nix { };

  nix-cmd = callPackage ../src/libcmd/package.nix { };

  nix-nswrapper = callPackage ../src/nswrapper/package.nix { };

  /**
    The Nix command line interface. Note that this does not include its tests, whereas `nix-everything` does.
  */
  nix-cli = callPackage ../src/nix/package.nix {
    version = fineVersion;
  };

  nix-functional-tests = callPackage ../tests/functional/package.nix {
    version = fineVersion;
  };

  /**
    The manual as would be published on https://nix.dev/reference/nix-manual
  */
  nix-manual = callPackage ../doc/manual/package.nix { version = fineVersion; };

  /**
    Manpages only (no HTML manual, no mdbook dependency)
  */
  nix-manual-manpages-only = callPackage ../doc/manual/package.nix {
    version = fineVersion;
    buildHtmlManual = false;
  };

  /**
    Doxygen pages for C++ code
  */
  nix-internal-api-docs = callPackage ../src/internal-api-docs/package.nix { version = fineVersion; };
  /**
    Doxygen pages for the public C API
  */
  nix-external-api-docs = callPackage ../src/external-api-docs/package.nix { version = fineVersion; };

  /**
    JSON schema validation checks
  */
  nix-json-schema-checks = callPackage ../src/json-schema-checks/package.nix { };

  # The clang-tidy plugin is a build-time tool loaded into clang-tidy itself,
  # so it must be built with a clang stdenv for ABI compatibility with the
  # clang-tidy binary from the same llvmPackages set, regardless of the
  # scope's stdenv (which may be GCC).
  nix-clang-tidy-plugin = callPackage ../src/clang-tidy-plugin/package.nix {
    llvmPackages = pkgs.buildPackages.llvmPackages;
    mkMesonDerivation = mkPackageBuilderFor pkgs.buildPackages.llvmPackages.stdenv [
      nixDefaultsLayer
      scope.sourceLayer
      setVersionLayer
      mesonLayer
      fixupStaticLayer
      scope.mesonComponentOverrides
    ];
  };

  /**
    Combined package that has the CLI, libraries, and (assuming non-cross, no overrides) it requires that all tests succeed.
  */
  nix-everything = callPackage ../packaging/everything.nix { } // {
    # Note: no `passthru.overrideAllMesonComponents` etc
    #       This would propagate into `nix.overrideAttrs f`, but then discard
    #       `f` when `.overrideAllMesonComponents` is used.
    #       Both "methods" should be views on the same fixpoint overriding mechanism
    #       for that to work. For now, we intentionally don't support the broken
    #       two-fixpoint solution.
    /**
      Apply an extension function (i.e. overlay-shaped) to all component derivations, and return the nix package.

      Single argument: the extension function to apply (finalAttrs: prevAttrs: { ... })
    */
    overrideAllMesonComponents = f: (scope.overrideAllMesonComponents f).nix-everything;

    /**
      Append patches to be applied to the whole Nix source.
      This affects all components.

      Changes to the packaging expressions will be ignored.

      Single argument: list of patches to apply

      See also `overrideSource`
    */
    appendPatches = ps: (scope.appendPatches ps).nix-everything;

    /**
      Provide an alternate source. This allows the expressions to be vendored without copying the sources,
      but it does make the build non-granular; all components will use a complete source.

      Packaging expressions will be ignored.

      Filesets in the packaging expressions will be ignored.

      Single argument: the source to use.

      See also `appendPatches`
    */
    overrideSource = src: (scope.overrideSource src).nix-everything;

    /**
      Override any internals of the Nix package set.

      Single argument: the extension function to apply to the package set (finalScope: prevScope: { ... })

      Example:
      ```
      overrideScope (finalScope: prevScope: { aws-crt-cpp = null; })
      ```
    */
    overrideScope = f: (scope.overrideScope f).nix-everything;

  };
}

{
  inputs,
  forAllCrossSystems,
  forAllSystems,
  lib,
  linux64BitSystems,
  nixpkgsFor,
  nixComponentsFor,
  self,
}:
let
  inherit (inputs) nixpkgs nixpkgs-regression;

  installScriptFor =
    tarballs:
    nixpkgsFor.x86_64-linux.native.callPackage ./installer {
      inherit tarballs;
      # Platform doesn't matter, we only need to fish out the fineVersion.
      version = nixComponentsFor.x86_64-linux.native.nix-cli.version;
    };

  testNixVersions =
    components: daemon:
    components.nix-functional-tests.override {
      pname = "nix-daemon-compat-tests";
      version = "${components.nix-cli.version}-with-daemon-${daemon.version}";

      test-daemon = daemon;
    };

  # Technically we could just return `nixComponents`, but for Hydra it's
  # convention to transpose it, and to transpose it efficiently, we need to
  # enumerate them manually, so that we don't evaluate unnecessary package sets.
  # See listingIsComplete below.
  forAllPackages = forAllPackages' { };
  forAllPackages' =
    {
      enableDocs ? false, # already have separate attrs for these
    }:
    lib.genAttrs (
      [
        "nix-everything"
        "nix-util"
        "nix-util-c"
        "nix-util-test-support"
        "nix-util-tests"
        "nix-store"
        "nix-store-c"
        "nix-store-test-support"
        "nix-store-tests"
        "nix-fetchers"
        "nix-fetchers-c"
        "nix-fetchers-tests"
        "nix-expr"
        "nix-expr-c"
        "nix-expr-test-support"
        "nix-expr-tests"
        "nix-flake"
        "nix-flake-c"
        "nix-flake-tests"
        "nix-nswrapper"
        "nix-main"
        "nix-main-c"
        "nix-cmd"
        "nix-cli"
        "nix-functional-tests"
        "nix-json-schema-checks"
        "nix-clang-tidy-plugin"
      ]
      ++ lib.optionals enableDocs [
        "nix-manual"
        "nix-manual-manpages-only"
        "nix-internal-api-docs"
        "nix-external-api-docs"
      ]
    );
in
rec {
  /**
    An internal check to make sure our package listing is complete.
  */
  listingIsComplete =
    let
      arbitrarySystem = "x86_64-linux";
      listedPkgs = forAllPackages' {
        enableDocs = true;
      } (_: null);
      actualPkgs = lib.concatMapAttrs (
        k: v: if lib.strings.hasPrefix "nix-" k then { ${k} = null; } else { }
      ) nixComponentsFor.${arbitrarySystem}.native;
      diff = lib.concatStringsSep "\n" (
        lib.concatLists (
          lib.mapAttrsToList (
            k: _:
            if (listedPkgs ? ${k}) && !(actualPkgs ? ${k}) then
              [ "- ${k}: redundant?" ]
            else if !(listedPkgs ? ${k}) && (actualPkgs ? ${k}) then
              [ "- ${k}: missing?" ]
            else
              [ ]
          ) (listedPkgs // actualPkgs)
        )
      );
    in
    if listedPkgs == actualPkgs then
      { }
    else
      throw ''
        Please update the components list in hydra.nix (or fix this check)
        Differences:
        ${diff}
      '';

  # Binary package for various platforms.
  build = forAllPackages (
    pkgName:
    lib.filterAttrs (
      system: _do_not_touch:
      pkgName == "nix-nswrapper" -> nixpkgsFor.${system}.native.stdenv.hostPlatform.isLinux
    ) (forAllSystems (system: nixComponentsFor.${system}.native.${pkgName}))
  );

  shellInputs = removeAttrs (forAllSystems (
    system: self.devShells.${system}.default.inputDerivation
  )) [ "i686-linux" ];

  buildStatic = forAllPackages (
    pkgName: lib.genAttrs linux64BitSystems (system: nixComponentsFor.${system}.nativeStatic.${pkgName})
  );

  buildCross = forAllPackages (
    pkgName:
    # Hack to avoid non-evaling package
    (
      if pkgName == "nix-functional-tests" then
        lib.flip builtins.removeAttrs [ "x86_64-w64-mingw32" ]
      else if pkgName == "nix-nswrapper" then
        lib.filterAttrs (
          crossSystem: _do_not_touch: nixpkgsFor.x86_64-linux.cross.${crossSystem}.stdenv.hostPlatform.isLinux
        )
      else
        lib.id
    )
      (
        forAllCrossSystems (
          crossSystem:
          lib.genAttrs [ "x86_64-linux" ] (system: nixComponentsFor.${system}.cross.${crossSystem}.${pkgName})
        )
      )
  );

  # Builds with sanitizers already have GC disabled, so this buildNoGc can just
  # point to buildWithSanitizers in order to reduce the load on hydra.
  buildNoGc = buildWithSanitizers;

  buildWithSanitizers =
    let
      components = forAllSystems (
        system:
        let
          components = nixComponentsFor.${system}.native;
          pkgs = components._pkgs;
        in
        nixComponentsFor.${system}.native.overrideScope (
          self: super: {
            # Boost coroutines fail with ASAN on darwin.
            withASan = !pkgs.stdenv.buildPlatform.isDarwin;
            withUBSan = true;
            # Build without unity to catch include issues.
            withUnityBuild = false;
            nix-expr = super.nix-expr.override { enableGC = false; };
          }
        )
      );
    in
    forAllPackages (
      pkgName:
      lib.filterAttrs (
        system: _do_not_touch:
        pkgName == "nix-nswrapper" -> nixpkgsFor.${system}.native.stdenv.hostPlatform.isLinux
      ) (forAllSystems (system: components.${system}.${pkgName}))
    );

  # Separate build because one cannot mix ASan + UBSan with TSan.
  buildWithTSan =
    let
      components =
        system:
        nixComponentsFor.${system}.native.overrideScope (
          self: super: {
            withTSan = true;
            # TSan has issues with fork and threads.
            nix-functional-tests = super.nix-functional-tests.overrideAttrs { doCheck = false; };
          }
        );
    in
    forAllPackages (pkgName: lib.genAttrs linux64BitSystems (system: (components system).${pkgName}));

  # Static analysis with clang-tidy
  clangTidy = lib.genAttrs linux64BitSystems (
    system:
    let
      tidyScope = nixComponentsFor.${system}.nativeForStdenv.clangStdenv.overrideScope (
        self: super: {
          withClangTidy = true;
          # clang-tidy doesn't seem to like unity builds.
          withUnityBuild = false;
          # nix-everything is built via callPackage (not the layer system), so
          # enableClangTidyLayer's doCheck=false doesn't reach it. Set it here
          # so checkInputs (the *-tests.tests.run derivations) aren't pulled in.
          nix-everything = super.nix-everything.overrideAttrs { doCheck = false; };
        }
      );
    in
    tidyScope.nix-everything
  );

  buildNoTests = forAllSystems (system: nixComponentsFor.${system}.native.nix-cli);

  # Toggles some settings for better coverage. Windows needs these
  # library combinations, and Debian build Nix with GNU readline too.
  buildReadlineNoMarkdown =
    let
      components = forAllSystems (
        system:
        nixComponentsFor.${system}.native.overrideScope (
          self: super: {
            nix-cmd = super.nix-cmd.override {
              enableMarkdown = false;
              readlineFlavor = "readline";
            };
          }
        )
      );
    in
    forAllPackages (
      pkgName:
      lib.filterAttrs (
        system: _do_not_touch:
        pkgName == "nix-nswrapper" -> nixpkgsFor.${system}.native.stdenv.hostPlatform.isLinux
      ) (forAllSystems (system: components.${system}.${pkgName}))
    );

  /**
    Config with the fewest libraries, so that dependency optionality doesn't regress.
  */
  buildMinimal =
    let
      components = forAllSystems (
        system:
        nixComponentsFor.${system}.native.overrideScope (
          self: super: {
            # No Boehm GC (libgc).
            nix-expr = super.nix-expr.override { enableGC = false; };
            # No Markdown rendering (lowdown).
            nix-cmd = super.nix-cmd.override { enableMarkdown = false; };
            # No S3 auth (aws-crt-cpp).
            nix-store = super.nix-store.override { withAWS = false; };
            # No mimalloc, no plugin C API.
            nix-cli = super.nix-cli.override {
              withMimalloc = false;
              withPluginCApi = false;
            };
            # Also, temporarily stuff newer libgit2 for more coverage of ifdefs.
            # Would be nicer for this to be somehow a private input, but we can't
            # override nixDependencies easily.
            libgit2 = self.callPackage (
              { pkgs, fetchFromGitHub }:
              pkgs.libgit2.overrideAttrs {
                version = "2.0.0-rc.1";
                src = fetchFromGitHub {
                  owner = "libgit2";
                  repo = "libgit2";
                  rev = "ae45d0d168f7e8dbfdb8c623589cb51caac96ab3";
                  hash = "sha256-3sbqHm37SOwBeFgtjI2DLN6kx1F7G2N1m6rRIkqDXNI=";
                };
              }
            ) { };
          }
        )
      );
    in
    forAllPackages (
      pkgName:
      lib.filterAttrs (
        system: _do_not_touch:
        pkgName == "nix-nswrapper" -> nixpkgsFor.${system}.native.stdenv.hostPlatform.isLinux
      ) (forAllSystems (system: components.${system}.${pkgName}))
    );

  # Binary tarball for various platforms, containing a Nix store
  # with the closure of 'nix' package, and the second half of
  # the installation script.
  binaryTarball = forAllSystems (
    system: nixComponentsFor.${system}.native.callPackage ./binary-tarball.nix { }
  );

  binaryTarballCross = lib.genAttrs [ "x86_64-linux" ] (
    system:
    forAllCrossSystems (
      crossSystem: nixComponentsFor.${system}.cross.${crossSystem}.callPackage ./binary-tarball.nix { }
    )
  );

  # The first half of the installation script. This is uploaded
  # to https://nixos.org/nix/install. It downloads the binary
  # tarball for the user's system and calls the second half of the
  # installation script.
  installerScript = installScriptFor [
    # Native
    self.hydraJobs.binaryTarball."x86_64-linux"
    self.hydraJobs.binaryTarball."i686-linux"
    self.hydraJobs.binaryTarball."aarch64-linux"
    self.hydraJobs.binaryTarball."aarch64-darwin"
    # Cross
    self.hydraJobs.binaryTarballCross."x86_64-linux"."armv6l-unknown-linux-gnueabihf"
    self.hydraJobs.binaryTarballCross."x86_64-linux"."armv7l-unknown-linux-gnueabihf"
    self.hydraJobs.binaryTarballCross."x86_64-linux"."powerpc64-unknown-linux-gnuabielfv1"
    self.hydraJobs.binaryTarballCross."x86_64-linux"."powerpc64le-unknown-linux-gnu"
    self.hydraJobs.binaryTarballCross."x86_64-linux"."riscv64-unknown-linux-gnu"
    self.hydraJobs.binaryTarballCross."x86_64-linux"."x86_64-unknown-freebsd"
  ];

  # TODO: Shouldn't even be part of hydraJobs. No tarballs should actually be needed
  # because those get taken from the --tarball-url-prefix argument.
  installerScriptForGHA = forAllSystems (
    system:
    nixpkgsFor.${system}.native.callPackage ./installer {
      tarballs = [ self.hydraJobs.binaryTarball.${system} ];
      # Platform doesn't matter, we only need to fish out the fineVersion.
      version = nixComponentsFor.x86_64-linux.native.nix-cli.version;
    }
  );

  # `NixOS/nix-installer` with this revision's Nix closure embedded.
  rustInstaller = lib.genAttrs (linux64BitSystems ++ [ "aarch64-darwin" ]) (
    system:
    let
      components = nixComponentsFor.${system}.native;
      pkgs = components._pkgs;
      # Embed the native (glibc) Nix even though the Linux installer
      # binary is static/musl.
      tarball = pkgs.callPackage ./rust-installer/tarball.nix {
        # TODO: Shouldn't this be nix-cli?
        nix = components.nix-everything;
      };
      builder = if pkgs.stdenv.hostPlatform.isLinux then pkgs.pkgsStatic else pkgs;
    in
    builder.callPackage ./rust-installer {
      inherit tarball;
    }
  );

  /**
    Docker image with Nix inside.
  */
  dockerImage = lib.genAttrs linux64BitSystems (
    system:
    let
      components = nixComponentsFor.${system}.native;
      pkgs = components._pkgs;
      image = pkgs.callPackage ../docker.nix {
        tag = components.nix-cli.version;
        # Override the nix used at build time to create the local store db. This is
        # the intended way to do this since https://github.com/NixOS/nixpkgs/pull/561007.
        # We are not doing cross builds yet, but splicing machinery should just work (tm)
        # if we do start.
        dockerTools = pkgs.dockerTools.override { nix = components.nix-cli; };
        nix = components.nix-cli;
      };
    in
    pkgs.runCommand "docker-image-tarball-${components.nix-cli.version}"
      { meta.description = "Docker image with Nix for ${system}"; }
      ''
        mkdir -p $out/nix-support
        image=$out/image.tar.gz
        ln -s ${image} $image
        echo "file binary-dist $image" >> $out/nix-support/hydra-build-products
      ''
  );

  # Line coverage analysis.
  coverage =
    (import ./../ci/gha/tests rec {
      withCoverage = true;
      pkgs = nixComponents._pkgs;
      nixComponents = nixComponentsFor.x86_64-linux.nativeForStdenv.clangStdenv;
      nixFlake = null;
      getStdenv = p: p.clangStdenv;
    }).codeCoverage.coverageReports.overrideAttrs
      {
        name = "nix-coverage"; # For historical consistency
      };

  /**
    Nix's manual
  */
  manual = nixComponentsFor.x86_64-linux.native.nix-manual;

  /**
    API docs for Nix's unstable internal C++ interfaces.
  */
  internal-api-docs = nixComponentsFor.x86_64-linux.native.nix-internal-api-docs;

  /**
    API docs for Nix's C bindings.
  */
  external-api-docs = nixComponentsFor.x86_64-linux.native.nix-external-api-docs;

  # System tests.
  tests =
    import ../tests/nixos rec {
      inherit lib nixpkgs;
      nixComponents = nixComponentsFor.x86_64-linux.native;
      pkgs = nixComponents._pkgs;
      inherit (self.inputs) nixpkgs-23-11;
    }
    // {

      # Make sure that nix-env still produces the exact same result
      # on a particular version of Nixpkgs.
      evalNixpkgs =
        let
          components = nixComponentsFor.x86_64-linux.native;
          inherit (components._pkgs) runCommand;
        in
        runCommand "eval-nixos" { buildInputs = [ components.nix-cli ]; } ''
          type -p nix-env
          # Note: we're filtering out nixos-install-tools because https://github.com/NixOS/nixpkgs/pull/153594#issuecomment-1020530593.
          (
            set -x
            time nix-env --store dummy:// -f ${nixpkgs-regression} -qaP --drv-path | sort | grep -v nixos-install-tools > packages
            [[ $(sha1sum < packages | cut -c1-40) = e01b031fc9785a572a38be6bc473957e3b6faad7 ]]
          )
          mkdir $out
        '';

      nixpkgsLibTests = forAllSystems (
        system:
        let
          components = nixComponentsFor.${system}.native;
          pkgs = components._pkgs;
        in
        import (nixpkgs + "/lib/tests/test-with-nix.nix") {
          inherit (pkgs) lib;
          inherit pkgs;
          nix = components.nix-cli;
        }
      );

      filetransfer-retry-backoff = forAllSystems (
        system: nixComponentsFor.${system}.native.callPackage ../tests/filetransfer-retry-backoff { }
      );

      /**
        Run functional tests with against set of nix daemon versions to catch
        protocol incompatibilities.
      */
      daemonCompat = forAllSystems (
        system:
        let
          components = nixComponentsFor.${system}.native;
          pkgs = components._pkgs;
        in
        pkgs.runCommand "daemon-compat-tests" {
          againstSelf = testNixVersions components components.nix-cli;
          againstCurrentLatest = testNixVersions components pkgs.nixVersions.latest;
          againstLatestStable = testNixVersions components pkgs.nixVersions.stable;
        } "touch $out"
      );

      /**
        Test the installer in QEMU VMs. Doesn't operate on the user-facing
        installation script https://nixos.org/nix/install, which downloads
        the binaries for the system architecture but the second-stage tarballs
        directly.
      */
      installer = import ../tests/installer {
        binaryTarballs = self.hydraJobs.binaryTarball;
        inherit nixpkgsFor;
        inherit lib;
      };
    };

  metrics.nixpkgs =
    let
      components = nixComponentsFor.x86_64-linux.native;
    in
    import "${nixpkgs-regression}/pkgs/top-level/metrics.nix" {
      nixpkgs = nixpkgs-regression;
      pkgs = components._pkgs // {
        nix = components.nix-cli;
      };
    };
}

